const listOperatingInitiatives = `-- name: ListOperatingInitiatives :many
SELECT id, workspace_id, pipeline_id, seq, title, thesis, stage_key, owner_squad_id, status, issue_id, build_project_id, source_proposal_id, sponsor_user_id, gate_days, stage_entered_at, shelved_at, operating_since, closed_at, closed_reason, created_at FROM initiative
WHERE status = 'operating' AND operating_since IS NOT NULL
ORDER BY workspace_id, seq
LIMIT $1::integer
`

// The gate job reads every initiative in its operate stage, across workspaces.
func (q *Queries) ListOperatingInitiatives(ctx context.Context, rowLimit int32) ([]Initiative, error) {
	rows, err := q.db.Query(ctx, listOperatingInitiatives, rowLimit)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	items := []Initiative{}
	for rows.Next() {
		var i Initiative
		if err := rows.Scan(
			&i.ID,
			&i.WorkspaceID,
			&i.PipelineID,
			&i.Seq,
			&i.Title,
			&i.Thesis,
			&i.StageKey,
			&i.OwnerSquadID,
			&i.Status,
			&i.IssueID,
			&i.BuildProjectID,
			&i.SourceProposalID,
			&i.SponsorUserID,
			&i.GateDays,
			&i.StageEnteredAt,
			&i.ShelvedAt,
			&i.OperatingSince,
			&i.ClosedAt,
			&i.ClosedReason,
			&i.CreatedAt,
		); err != nil {
			return nil, err
		}
		items = append(items, i)
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}

const listPendingGateProposalsForWorkspace = `-- name: ListPendingGateProposalsForWorkspace :many
SELECT p.id AS proposal_id, (p.payload->>'initiative_id')::text AS initiative_id, p.created_at
FROM proposal p
WHERE p.workspace_id = $1::uuid
  AND p.kind = 'stage_gate'
  AND p.state = 'pending'
ORDER BY p.created_at DESC, p.id DESC
`

type ListPendingGateProposalsForWorkspaceRow struct {
	ProposalID   pgtype.UUID        `json:"proposal_id"`
	InitiativeID string             `json:"initiative_id"`
	CreatedAt    pgtype.Timestamptz `json:"created_at"`
}

// Pending stage_gate proposals of the workspace, with the initiative they name.
func (q *Queries) ListPendingGateProposalsForWorkspace(ctx context.Context, workspaceID pgtype.UUID) ([]ListPendingGateProposalsForWorkspaceRow, error) {
	rows, err := q.db.Query(ctx, listPendingGateProposalsForWorkspace, workspaceID)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	items := []ListPendingGateProposalsForWorkspaceRow{}
	for rows.Next() {
		var i ListPendingGateProposalsForWorkspaceRow
		if err := rows.Scan(&i.ProposalID, &i.InitiativeID, &i.CreatedAt); err != nil {
			return nil, err
		}
		items = append(items, i)
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}

const lockInitiativeInWorkspace = `-- name: LockInitiativeInWorkspace :one
SELECT id, workspace_id, pipeline_id, seq, title, thesis, stage_key, owner_squad_id, status, issue_id, build_project_id, source_proposal_id, sponsor_user_id, gate_days, stage_entered_at, shelved_at, operating_since, closed_at, closed_reason, created_at FROM initiative
WHERE id = $1::uuid AND workspace_id = $2::uuid
FOR UPDATE
`

type LockInitiativeInWorkspaceParams struct {
	ID          pgtype.UUID `json:"id"`
	WorkspaceID pgtype.UUID `json:"workspace_id"`
}

// Row lock for a transition, so two concurrent moves cannot both read the same
// stage.
func (q *Queries) LockInitiativeInWorkspace(ctx context.Context, arg LockInitiativeInWorkspaceParams) (Initiative, error) {
	row := q.db.QueryRow(ctx, lockInitiativeInWorkspace, arg.ID, arg.WorkspaceID)
	var i Initiative
	err := row.Scan(
		&i.ID,
		&i.WorkspaceID,
		&i.PipelineID,
		&i.Seq,
		&i.Title,
		&i.Thesis,
		&i.StageKey,
		&i.OwnerSquadID,
		&i.Status,
		&i.IssueID,
		&i.BuildProjectID,
		&i.SourceProposalID,
		&i.SponsorUserID,
		&i.GateDays,
		&i.StageEnteredAt,
		&i.ShelvedAt,
		&i.OperatingSince,
		&i.ClosedAt,
		&i.ClosedReason,
		&i.CreatedAt,
	)
	return i, err
}

const lockInitiativeWorkspace = `-- name: LockInitiativeWorkspace :exec

SELECT pg_advisory_xact_lock(hashtext('initiative'), hashtext($1::uuid::text))
`

// Initiatives, their stage timeline and their artifact checklists (spec 3.1).
// Every query filters by workspace_id.
// Serializes initiative creation within one workspace, so seq is unique under
// concurrent creates (the unique index is the backstop). Released at commit.
func (q *Queries) LockInitiativeWorkspace(ctx context.Context, workspaceID pgtype.UUID) error {
	_, err := q.db.Exec(ctx, lockInitiativeWorkspace, workspaceID)
	return err
}

const minIssuePositionInStatus = `-- name: MinIssuePositionInStatus :one
SELECT COALESCE(MIN(position), 0)::float8 FROM issue
WHERE workspace_id = $1::uuid AND status = $2::text
`

type MinIssuePositionInStatusParams struct {
	WorkspaceID pgtype.UUID `json:"workspace_id"`
	Status      string      `json:"status"`
}

// The top of a status column, for placing an issue the initiative service
// creates (the issue service's NextTopPosition rule).
func (q *Queries) MinIssuePositionInStatus(ctx context.Context, arg MinIssuePositionInStatusParams) (float64, error) {
	row := q.db.QueryRow(ctx, minIssuePositionInStatus, arg.WorkspaceID, arg.Status)
	var column_1 float64
	err := row.Scan(&column_1)
	return column_1, err
}

const nextInitiativeSeq = `-- name: NextInitiativeSeq :one
SELECT (COALESCE(MAX(seq), 0) + 1)::integer AS next_seq FROM initiative
WHERE workspace_id = $1::uuid
`

func (q *Queries) NextInitiativeSeq(ctx context.Context, workspaceID pgtype.UUID) (int32, error) {
	row := q.db.QueryRow(ctx, nextInitiativeSeq, workspaceID)
	var next_seq int32
	err := row.Scan(&next_seq)
	return next_seq, err
}

